create table pw_game (id bigint generated by default as identity primary key, game_code varchar(64) not null unique, game_name varchar(64) not null, icon_url varchar(512), cover_url varchar(512), platform_type varchar(16) not null, description varchar(500), sort_no integer not null default 0, enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create table pw_game_position (id bigint generated by default as identity primary key, game_id bigint not null, position_code varchar(64) not null, position_name varchar(64) not null, icon_url varchar(512), sort_no integer not null default 0, enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp, unique(game_id,position_code));
create table pw_player (id bigint generated by default as identity primary key, player_no varchar(32) not null unique, user_id bigint unique, nickname varchar(64) not null, real_name varchar(64), gender varchar(16) not null default 'UNKNOWN', phone varchar(32), email varchar(128), avatar_url varchar(512), cover_url varchar(512), introduction varchar(1000), voice_url varchar(512), audit_status varchar(16) not null default 'DRAFT', work_status varchar(16) not null default 'OFFLINE', enabled boolean not null default true, audit_remark varchar(500), approved_at timestamp, last_online_at timestamp, order_count integer not null default 0, rating_score decimal(4,2) not null default 0, rating_count integer not null default 0, sort_no integer not null default 0, remark varchar(500), created_by bigint, created_at timestamp not null default current_timestamp, updated_by bigint, updated_at timestamp not null default current_timestamp);
create table pw_player_game (id bigint generated by default as identity primary key, player_id bigint not null, game_id bigint not null, game_nickname varchar(64), game_account varchar(128), server_name varchar(128), rank_name varchar(64), rank_level integer, experience_years integer, introduction varchar(500), proof_url varchar(512), is_primary boolean not null default false, audit_status varchar(16) not null default 'PENDING', audit_remark varchar(500), enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp, unique(player_id,game_id));
create table pw_player_game_position (id bigint generated by default as identity primary key, player_game_id bigint not null, position_id bigint not null, skill_level varchar(32), is_primary boolean not null default false, created_at timestamp not null default current_timestamp, unique(player_game_id,position_id));
create table pw_player_tag (id bigint generated by default as identity primary key, tag_code varchar(64) not null unique, tag_name varchar(64) not null, tag_color varchar(32), tag_group varchar(16) not null default 'OTHER', sort_no integer not null default 0, enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create table pw_player_tag_rel (player_id bigint not null, tag_id bigint not null, created_at timestamp not null default current_timestamp, primary key(player_id,tag_id));
create table pw_player_media (id bigint generated by default as identity primary key, player_id bigint not null, media_type varchar(32) not null, media_url varchar(512) not null, thumbnail_url varchar(512), title varchar(128), sort_no integer not null default 0, audit_status varchar(16) not null default 'PENDING', audit_remark varchar(500), enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create table pw_player_audit (id bigint generated by default as identity primary key, player_id bigint not null, audit_type varchar(16) not null, before_status varchar(16), after_status varchar(16) not null, result varchar(16) not null, reason varchar(500), snapshot_data varchar(4000), auditor_id bigint, audited_at timestamp, created_at timestamp not null default current_timestamp);
create table pw_player_status_log (id bigint generated by default as identity primary key, player_id bigint not null, status_type varchar(32) not null, before_value varchar(32), after_value varchar(32) not null, reason varchar(500), operator_type varchar(16) not null, operator_id bigint, created_at timestamp not null default current_timestamp);
create index ix_pw_player_status on pw_player(audit_status,work_status,enabled);
create index ix_pw_player_game_player on pw_player_game(player_id);
create index ix_pw_player_media_player on pw_player_media(player_id);
create index ix_pw_player_audit_player on pw_player_audit(player_id);
create index ix_pw_player_status_log_player on pw_player_status_log(player_id);

insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no)
select null,'DIRECTORY','Business','/business','/index/index','业务管理','ri:briefcase-4-line',20 where not exists(select 1 from sys_menu where name='Business');
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','Player','player','/business/player','陪玩师管理','ri:user-star-line',1 from sys_menu where name='Business';
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','Game','game','/business/game','游戏管理','ri:gamepad-line',2 from sys_menu where name='Business';
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','PlayerTag','player-tag','/business/player-tag','陪玩师标签','ri:price-tag-3-line',3 from sys_menu where name='Business';
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat(p.name,a.action_name),a.title,a.auth_mark,a.sort_no from sys_menu p join (
 select 'Player' parent_name,'List' action_name,'查询陪玩师' title,'business:player:list' auth_mark,1 sort_no union all select 'Player','Create','新增陪玩师','business:player:create',2 union all select 'Player','Update','编辑陪玩师','business:player:update',3 union all select 'Player','Status','修改陪玩师状态','business:player:status',4 union all select 'Player','Audit','审核陪玩师','business:player:audit',5 union all select 'Player','Detail','管理陪玩师资料','business:player:detail',6 union all
 select 'Game','List','查询游戏','business:game:list',1 union all select 'Game','Create','新增游戏','business:game:create',2 union all select 'Game','Update','编辑游戏','business:game:update',3 union all select 'Game','Status','修改游戏状态','business:game:status',4 union all select 'Game','Delete','删除游戏','business:game:delete',5 union all
 select 'PlayerTag','List','查询标签','business:player-tag:list',1 union all select 'PlayerTag','Create','新增标签','business:player-tag:create',2 union all select 'PlayerTag','Update','编辑标签','business:player-tag:update',3 union all select 'PlayerTag','Delete','删除标签','business:player-tag:delete',4
) a on a.parent_name=p.name;
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
